mapper.update:
UPDATE ALIPAY_PAY_LOG
SET PAY_STATUS = #{payStatus,jdbcType=VARCHAR}
WHERE PAY_SEQ = #{paySeq,jdbcType=VARCHAR}

mapper.select:
SELECT * FROM ( SELECT , ROW_NUMBER() OVER (ORDER BY PAY_SEQ DESC) AS rn FROM ALIPAY_PAY_LOG WHERE 1=1
AND THIRD_USER_ID = #{thirdUserId}
AND PAY_STATUS = 'SUCCESS'
AND PAY_STATUS != 'SUCCESS'
AND INVOICE = #{invoice}
AND TO_DATE(TRANS_TIME, 'YYYY-MM-DD HH24:MI:SS') >= TO_DATE(#{startTime}, 'YYYY-MM-DD')
AND TO_DATE(TRANS_TIME, 'YYYY-MM-DD HH24:MI:SS') < TO_DATE(#{endTime}, 'YYYY-MM-DD') + 1
) WHERE rn > #{offset} AND rn <= #{limit}
